package io.github.diodeme.ji.host;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

final class RetentionLogTest {
    @TempDir java.nio.file.Path directory;
    private static final Instant NOW = Instant.parse("2026-09-06T00:00:00Z");

    @Test
    void auditAndDiagnosticRecordsExpireAtIndependentFixedBoundaries() throws Exception {
        var audit = new RetentionLog(directory.resolve("audit.ndjson"), Duration.ofDays(90), 4096);
        var diagnostics = new RetentionLog(directory.resolve("diagnostics.ndjson"), Duration.ofDays(14), 4096);
        audit.append(new RetentionLog.Entry("audit-old", NOW.minus(Duration.ofDays(91)), "device.revoked", Map.of("deviceId", "d1")));
        audit.append(new RetentionLog.Entry("audit-current", NOW.minus(Duration.ofDays(90)), "permission.resolved", Map.of("permissionId", "p1")));
        diagnostics.append(new RetentionLog.Entry("diag-old", NOW.minus(Duration.ofDays(15)), "provider.timeout", Map.of("provider", "openai")));
        diagnostics.append(new RetentionLog.Entry("diag-current", NOW.minus(Duration.ofDays(14)), "host.ready", Map.of("status", "ready")));

        assertEquals(1, audit.purge(NOW));
        assertEquals(1, diagnostics.purge(NOW));
        assertEquals(java.util.List.of("audit-current"), audit.entries().stream().map(RetentionLog.Entry::id).toList());
        assertEquals(java.util.List.of("diag-current"), diagnostics.entries().stream().map(RetentionLog.Entry::id).toList());
        assertTrue(Files.readString(directory.resolve("audit.ndjson")).contains("audit-current"));
    }

    @Test
    void fieldsAreAllowListedAndNewlinesCannotForgeRecords() {
        var log = new RetentionLog(directory.resolve("safe.ndjson"), Duration.ofDays(14), 1024);
        log.append(new RetentionLog.Entry("entry-1", NOW, "provider.failure", Map.of(
                "operationId", "operation-1", "message", "secret\nforged")));

        var entry = log.entries().getFirst();
        assertEquals(Map.of("operationId", "operation-1"), entry.fields());
    }
}
